32	/**
33	 * Simple JavaBean domain object representing an owner.
34	 *
35	 * @author Ken Krebs
36	 * @author Juergen Hoeller
37	 * @author Sam Brannen
38	 * @author Michael Isvy
39	 */
40	@Entity
41	@Table(name = "owners")
42	public class Owner extends Person {
43	    @Column(name = "title")
44	    private String title;
45	
46	    @Column(name = "address")
47	    @NotEmpty
48	    private String address;
49	
50	    @Column(name = "address_line1")
51	    private String addressLine1;
52	
53	    @Column(name = "address_line2")
54	    private String addressLine2;
55	
56	    @Column(name = "city")
57	    @NotEmpty
58	    private String city;
59	
60	    @Column(name = "telephone")
61	    @NotEmpty
62	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
63	    private String telephone;
64	
65	    @Column(name = "email")
66	    private String email;
67	
68	    @Column(name = "postcode")
69	    private String postcode;
70	
71	    @Column(name = "registration_date")
72	    private LocalDate registrationDate;
73	
74	    @Column(name = "birth_date")
75	    private LocalDate birthDate;
76	
77	    @Column(name = "customer_code")
78	    private String customerCode;
79	
80	    @Column(name = "household_id")
81	    private String householdId;
82	
83	    @Column(name = "namesake_count")
84	    private Integer namesakeCount;
85	
86	    @Column(name = "household_size")
87	    private Integer householdSize;
88	
89	    @Column(name = "membership_number")
90	    private String membershipNumber;
91	
92	    @Column(name = "membership_level_cap")
93	    private Integer membershipLevelCap;
94	
95	    @Column(name = "possible_duplicate_of")
96	    private Integer possibleDuplicateOf;
97	
98	    @Column(name = "deleted", nullable = false)
99	    private boolean deleted;
100	
101	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
102	    private Set<Pet> pets;
103	
104	    /**
105	     * Default the registration date to the server's current date when none was
106	     * supplied, then roll the effective date forward onto a business day so a
107	     * weekend registration date always lands on the following Monday. Runs only
108	     * on insert.
109	     */
110	    @PrePersist
111	    private void defaultRegistrationDate() {
112	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
113	        this.registrationDate = BusinessDayAdjuster.toBusinessDay(effectiveDate);
114	    }
115	
116	    public String getTitle() {
117	        return this.title;
118	    }
119	
120	    public void setTitle(String title) {
121	        this.title = title;
122	    }
123	
124	    public String getAddress() {
125	        return this.address;
126	    }
127	
128	    public void setAddress(String address) {
129	        this.address = address;
130	    }
131	
132	    public String getAddressLine1() {
133	        return this.addressLine1;
134	    }
135	
136	    public void setAddressLine1(String addressLine1) {
137	        this.addressLine1 = addressLine1;
138	    }
139	
140	    public String getAddressLine2() {
141	        return this.addressLine2;
142	    }
143	
144	    public void setAddressLine2(String addressLine2) {
145	        this.addressLine2 = addressLine2;
146	    }
147	
148	    public String getCity() {
149	        return this.city;
150	    }
151	
152	    public void setCity(String city) {
153	        this.city = city;
154	    }
155	
156	    public String getTelephone() {
157	        return this.telephone;
158	    }
159	
160	    public void setTelephone(String telephone) {
161	        this.telephone = telephone;
162	    }
163	
164	    public String getEmail() {
165	        return this.email;
166	    }
167	
168	    public void setEmail(String email) {
169	        this.email = email;
170	    }
171	
172	    public String getPostcode() {
173	        return this.postcode;
174	    }
175	
176	    public void setPostcode(String postcode) {
177	        this.postcode = postcode;
178	    }
179	
180	    public LocalDate getRegistrationDate() {
181	        return this.registrationDate;
182	    }
183	
184	    public void setRegistrationDate(LocalDate registrationDate) {
185	        this.registrationDate = registrationDate;
186	    }
187	
188	    public LocalDate getBirthDate() {
189	        return this.birthDate;
190	    }
191	
192	    public void setBirthDate(LocalDate birthDate) {
193	        this.birthDate = birthDate;
194	    }
195	
196	    public String getCustomerCode() {
197	        return this.customerCode;
198	    }
199	
200	    public void setCustomerCode(String customerCode) {
201	        this.customerCode = customerCode;
202	    }
203	
204	    /**
205	     * Return this owner's primary identifier: the single value that currently identifies the owner
206	     * to the outside world. Today that is the {@link #getCustomerCode() customer code}; when the
207	     * customer code is later unified into the member id, this method returns the member id instead,
208	     * so callers such as the audit trail always follow the current identifier without change.
209	     */
210	    @Transient
211	    public String getPrimaryIdentifier() {
212	        return getCustomerCode();
213	    }
214	
215	    public String getHouseholdId() {
216	        return this.householdId;
217	    }
218	
219	    public void setHouseholdId(String householdId) {
220	        this.householdId = householdId;
221	    }
222	
223	    public Integer getNamesakeCount() {
224	        return this.namesakeCount;
225	    }
226	
227	    public void setNamesakeCount(Integer namesakeCount) {
228	        this.namesakeCount = namesakeCount;
229	    }
230	
231	    public Integer getHouseholdSize() {
232	        return this.householdSize;
233	    }
234	
235	    public void setHouseholdSize(Integer householdSize) {
236	        this.householdSize = householdSize;
237	    }
238	
239	    public String getMembershipNumber() {
240	        return this.membershipNumber;
241	    }
242	
243	    public void setMembershipNumber(String membershipNumber) {
244	        this.membershipNumber = membershipNumber;
245	    }
246	
247	    public Integer getMembershipLevelCap() {
248	        return this.membershipLevelCap;
249	    }
250	
251	    public void setMembershipLevelCap(Integer membershipLevelCap) {
252	        this.membershipLevelCap = membershipLevelCap;
253	    }
254	
255	    public Integer getPossibleDuplicateOf() {
256	        return this.possibleDuplicateOf;
257	    }
258	
259	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
260	        this.possibleDuplicateOf = possibleDuplicateOf;
261	    }
262	
263	    /**
264	     * Return whether this owner has been soft-deleted. A newly created owner is not deleted; a
265	     * {@code DELETE /api/owners/{id}} flags the owner deleted while retaining its record.
266	     */
267	    public boolean isDeleted() {
268	        return this.deleted;
269	    }
270	
271	    public void setDeleted(boolean deleted) {
272	        this.deleted = deleted;
273	    }
274	
275	    /**
276	     * Return this owner's self link: the canonical API path of this owner, {@code /api/owners/}
277	     * followed by its {@link #getId() id}.
278	     */
279	    @Transient
280	    public String getSelfLink() {
281	        return "/api/owners/" + this.getId();
282	    }
283	
284	    /**
285	     * Return whether this owner is a possible duplicate: true when it was created while an existing
286	     * owner's last name shared its Soundex code at the same postcode (yet resolved to a different
287	     * identity key), i.e. when a {@link #getPossibleDuplicateOf() possible-duplicate-of} owner id is
288	     * present.
289	     */
290	    @Transient
291	    public boolean getPossibleDuplicate() {
292	        return this.possibleDuplicateOf != null;
293	    }
294	
295	    /**
296	     * Return this owner's name formatted as {@code LastName, FirstName}.
297	     */
298	    @Transient
299	    public String getDisplayName() {
300	        return this.getLastName() + ", " + this.getFirstName();
301	    }
302	
303	    /**
304	     * Return this owner's salutation: the {@link #getTitle() title} followed by a space and the
305	     * last name (e.g. {@code DR Franklin}), or just the last name when no title was supplied.
306	     */
307	    @Transient
308	    public String getSalutation() {
309	        if (this.title == null || this.title.isBlank()) {
310	            return this.getLastName();
311	        }
312	        return this.title + " " + this.getLastName();
313	    }
314	
315	    /**
316	     * Return this owner's telephone formatted for human display: the country code, a space, then
317	     * the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The raw
318	     * {@link #getTelephone() telephone} remains in canonical E.164 form.
319	     */
320	    @Transient
321	    public String getTelephoneDisplay() {
322	        return TelephoneFormatter.format(this.telephone);
323	    }
324	
325	    /**
326	     * Return this owner's identity key: the lower-case SHA-256 hex digest of
327	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (an absent email
328	     * contributes an empty segment). Two owners are the same person — a hard duplicate — exactly
329	     * when their identity keys match; owners who merely share a household (same last name and
330	     * postcode) but differ in telephone, email or surname sound derive distinct keys. The telephone
331	     * and email are expected to already be in their normalized storage form.
332	     */
333	    @Transient
334	    public String getIdentityKey() {
335	        String raw = orEmpty(this.telephone) + "|" + orEmpty(this.email).toLowerCase(Locale.ROOT)
336	            + "|" + Soundex.encode(this.getLastName());
337	        return Sha256.hex(raw);
338	    }
339	
340	    private static String orEmpty(String value) {
341	        return value == null ? "" : value;
342	    }
343	
344	    /**
345	     * Return this owner's locality: the REGION segment of the owner's
346	     * {@link #getCustomerCode() customer code}, which is the region the identity was minted for.
347	     * When no customer code has been assigned yet the region is resolved directly from the
348	     * {@link #getPostcode() postcode} and {@link #getCity() city} via {@link RegionResolver}.
349	     */
350	    @Transient
351	    public String getLocality() {
352	        if (this.customerCode != null && !this.customerCode.isBlank()) {
353	            return CustomerCodeGenerator.regionOf(this.customerCode);
354	        }
355	        return RegionResolver.regionFor(this.postcode, this.city);
356	    }
357	
358	    /**
359	     * Return this owner's timezone: the IANA name mapped from the owner's
360	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table. Null when the
361	     * region has no known timezone.
362	     */
363	    @Transient
364	    public String getTimezone() {
365	        return RegionTimezones.timezoneOf(getLocality());
366	    }
367	
368	    /**
369	     * Return this owner's marketing segment, formatted {@code <TIER>_<AREA>}: the TIER is
370	     * {@code PREMIUM} when the owner's {@link #getMembershipLevel() membership level} is 3 or more,
371	     * otherwise {@code STANDARD}; the AREA is {@code METRO} when the owner's {@link #getLocality()
372	     * locality} is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
373	     */
374	    @Transient
375	    public String getOwnerSegment() {
376	        return OwnerSegment.of(getMembershipLevel(), getLocality());
377	    }
378	
379	    /**
380	     * Return this owner's membership points: starting at 0, plus 2 when the owner has an email,
381	     * plus 1 when the owner is uniquely named (a {@link #getNamesakeCount() namesakeCount} of 0),
382	     * plus 2 for a household of three or more ({@link #getHouseholdSize() household size}), plus 3
383	     * for long tenure ({@link #getTenureFiscalYears() tenure} of more than one fiscal year).
384	     */
385	    @Transient
386	    public int getMembershipPoints() {
387	        boolean hasEmail = this.email != null && !this.email.isEmpty();
388	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
389	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
390	        boolean longTenure = getTenureFiscalYears() > 1;
391	        return MembershipPoints.of(hasEmail, uniquelyNamed, largeHousehold, longTenure);
392	    }
393	
394	    /**
395	     * Return this owner's membership level: the band their {@link #getMembershipPoints() membership
396	     * points} fall into — 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more — capped so it
397	     * never exceeds one above the highest level among the household members present when this owner
398	     * was created (see {@link #getMembershipLevelCap() membership level cap}). No cap applies to an
399	     * owner created without any existing household member.
400	     */
401	    @Transient
402	    public int getMembershipLevel() {
403	        int level = MembershipPoints.levelFor(getMembershipPoints());
404	        return this.membershipLevelCap == null ? level : Math.min(level, this.membershipLevelCap);
405	    }
406	
407	    /**
408	     * Return this owner's fiscal year: the fiscal year of the business-day-adjusted
409	     * {@link #getRegistrationDate() registration date}, formatted {@code FY<YY>}. The fiscal year
410	     * starts on 1 July. Null when no registration date is known.
411	     */
412	    @Transient
413	    public String getFiscalYear() {
414	        return this.registrationDate == null ? null : FiscalYear.labelOf(this.registrationDate);
415	    }
416	
417	    /**
418	     * Return this owner's tenure in whole fiscal years: the number of fiscal years elapsed from the
419	     * {@link #getRegistrationDate() registration date} to today, i.e. the count of 1 July
420	     * fiscal-year boundaries crossed. A newly created owner registered in the current fiscal year
421	     * has zero tenure. Zero when no registration date is known.
422	     */
423	    @Transient
424	    public int getTenureFiscalYears() {
425	        if (this.registrationDate == null) {
426	            return 0;
427	        }
428	        return FiscalYear.elapsedBetween(this.registrationDate, LocalDate.now());
429	    }
430	
431	    /**
432	     * Return this owner's check digit: the single Luhn check digit computed over the
433	     * digits of the {@link #getCustomerCode() customer code}.
434	     */
435	    @Transient
436	    public int getCheckDigit() {
437	        return LuhnCheckDigit.of(this.customerCode);
438	    }
439	
440	    /**
441	     * Return this owner's preferred contact channel: {@code EMAIL} when an
442	     * {@link #getEmail() email} is present, otherwise {@code PHONE}.
443	     */
444	    @Transient
445	    public String getContactPreference() {
446	        boolean hasEmail = this.email != null && !this.email.isEmpty();
447	        return hasEmail ? "EMAIL" : "PHONE";
448	    }
449	
450	    /**
451	     * Return this owner's age band as of the {@link #getRegistrationDate() registration date},
452	     * derived from the {@link #getBirthDate() birth date}: {@code MINOR} under 18, {@code ADULT}
453	     * from 18 to 64, {@code SENIOR} at 65 or older. Null when no birth date is known.
454	     */
455	    @Transient
456	    public String getAgeBand() {
457	        AgeBand ageBand = AgeBand.asOf(this.birthDate, this.registrationDate);
458	        return ageBand == null ? null : ageBand.name();
459	    }
460	
461	    protected Set<Pet> getPetsInternal() {
462	        if (this.pets == null) {
463	            this.pets = new HashSet<>();
464	        }
465	        return this.pets;
466	    }
467	
468	    protected void setPetsInternal(Set<Pet> pets) {
469	        this.pets = pets;
470	    }
471	
472	    public List<Pet> getPets() {
473	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
474	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
475	        return Collections.unmodifiableList(sortedPets);
476	    }
477	
478	    public void setPets(List<Pet> pets) {
479	        this.pets = new HashSet<>(pets);
480	    }
481	
482	    public void addPet(Pet pet) {
483	        getPetsInternal().add(pet);
484	        pet.setOwner(this);
485	    }
486	
487	    /**
488	     * Return the Pet with the given name, or null if none found for this Owner.
489	     *
490	     * @param name to test
491	     * @return true if pet name is already in use
492	     */
493	    public Pet getPet(String name) {
494	        return getPet(name, false);
495	    }
496	
497	    /**
498	     * Return the Pet with the given name, or null if none found for this Owner.
499	     *
500	     * @param name to test
501	     * @return true if pet name is already in use
502	     */
503	    public Pet getPet(String name, boolean ignoreNew) {
504	        name = name.toLowerCase();
505	        for (Pet pet : getPetsInternal()) {
506	            if (!ignoreNew || !pet.isNew()) {
507	                String compName = pet.getName();
508	                compName = compName.toLowerCase();
509	                if (compName.equals(name)) {
510	                    return pet;
511	                }
512	            }
513	        }
514	        return null;
515	    }
516	
517	    public Pet getPet(Integer petId) {
518	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
519	    }
520	
521	    @Override
522	    public String toString() {
523	        return new ToStringCreator(this)
524	
525	            .append("id", this.getId())
526	            .append("new", this.isNew())
527	            .append("lastName", this.getLastName())
528	            .append("firstName", this.getFirstName())
529	            .append("address", this.address)
530	            .append("city", this.city)
531	            .append("telephone", this.telephone)
532	            .append("email", this.email)
533	            .toString();
534	    }
535	}
