163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
166	        Optional<Owner> replay = replayForIdempotencyKey(idempotencyKey);
167	        if (replay.isPresent()) {
168	            return new ResponseEntity<>(ownerMapper.toOwnerDto(replay.get()), HttpStatus.OK);
169	        }
170	        Owner owner = createOwner(ownerFieldsDto);
171	        rememberForIdempotencyKey(idempotencyKey, owner);
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        HttpHeaders headers = new HttpHeaders();
174	        headers.setLocation(UriComponentsBuilder.newInstance()
175	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
176	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
177	    }
