230	    /**
231	     * Normalize the submitted address fields and resolve the effective {@code address}. The
232	     * structured lines are normalized in place; when a non-blank {@code addressLine1} is supplied it
233	     * takes precedence and {@code address} is composed from the normalized lines, otherwise the flat
234	     * {@code address} input is normalized and kept for backward compatibility.
235	     */
236	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
237	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
238	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
239	        ownerFieldsDto.setAddressLine1(line1);
240	        ownerFieldsDto.setAddressLine2(line2);
241	        if (line1 != null && !line1.isBlank()) {
242	            ownerFieldsDto.setAddress(AddressNormalizer.compose(line1, line2));
243	        } else {
244	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
245	        }
246	    }
